def main():
    raw=(ROOT/'docs/MINDMAP_V4_CONTENT_RECONCILIATION_RU.md').read_text(encoding='utf-8')
    raw=raw[raw.index('# Psyz0r_bot'):]
    raw=raw.replace('Mind Map v4 — текстовая сверка перед отрисовкой','Mind Map v5 — актуализированная логика')
    raw=raw.replace('Дата сверки: 12.10.2026. Рисование не начато.', 'Дата актуализации: 19.10.2026. Основа v4 сохранена по ID; добавлены последние требования и документальные свидетельства этапа 0.7.4. Сервер в этом выпуске заново не опрашивался.')
    for ident,(status,text) in UPDATES.items():
        raw,count=re.subn(r'^- `'+ident+r' [^`]+` .*$',f'- `{ident} {status}` {text}',raw,flags=re.M)
        assert count==1,ident
    for letter,rows in ADDITIONS.items():
        pattern=r'(^## '+letter+r'\. .*?)(?=^## |\Z)'
        match=re.search(pattern,raw,re.M|re.S);assert match,letter
        block=match.group(1)
        numbers=[int(n) for n in re.findall(r'^- `'+letter+r'(\d+)',block,re.M)]
        start=max(numbers)+1
        extra='\n'.join(f'- `{letter}{start+i:02d} {status}` {text}' for i,(status,text) in enumerate(rows))
        raw=raw[:match.start()]+block.rstrip()+'\n'+extra+'\n\n'+raw[match.end():]
    # Keep the ambiguity list current; preserve all eight historical topics.
    raw=raw.replace('2. Порог gauntlet revenge: тестовый 25, основной предложенный 50, ранний диапазон 50–100; HP-only против HP+armor.', '2. Порог мести уточнён: 50 с усилением 100/150; прежний 25 отменён. Способ суммирования HP и брони нужно явно задать/проверить; логировать оба значения.')
    raw=raw.replace('1. Частота сильного тильта: раннее `1–2/100`, позднее `1–2/10–15`.', '1. Частота слива лидерства остаётся вариантом характера; не смешивать её с последним ориентиром раннего ухода 1–2/10 при сильном отставании.')
    raw=raw.replace('6. Тотальный контроль при сильном сопернике против правила редкости 1–2/10; строгий контроль основных ресурсов нужно считать отдельным режимом.', '6. Для текущего сильного тестового профиля разрешён выгодный контроль без искусственной редкости; прежние 1–2/10 остаются отдельной настройкой характера, не багом ресурсов.')
    raw += '\n## Новые источники v5\n\n- [Требования владельца 19.10](OWNER_REQUIREMENTS_20261019_RU.md).\n- [Этап 0.7.4](PREALPHA_0_7_4_RU.md), [дополнение](LOGIC_ADDENDUM_074_RU.md).\n- LG: `training/LG_FOOTWORK_075.json`; разбор окон 500 демо, без сырых клавиш и без траекторий чужих ракет.\n- WEB-панель — PAUSED, новая идея владельца; существующий HTML является статическим просмотром карты.\n'
    (ROOT/'docs/MINDMAP_V5_CONTENT_RECONCILIATION_RU.md').write_text(raw,encoding='utf-8')

if __name__=='__main__':main()
